# Get robot position and locate candidate tools on the shelf (hammer, wrench, screwdriver)
r = primitives.call(name='submit_capx_action', action='get_robot_position', native_api=True, parameters={})
print('robot', r.ok, str(r.output)[:600])
found = {}
for nm in ['hammer', 'wrench', 'screwdriver', 'pliers', 'tape measure']:
    rr = primitives.call(name='submit_capx_action', action='get_object_pose', native_api=True, parameters={'object_name': nm, 'return_bbox_extent': True})
    if rr.ok:
        res = rr.output['native_api_result']
        try:
            pos = res[0]['values']; ext = res[2]['values']
            found[nm] = (pos, ext)
            print(nm, [round(x,3) for x in pos], [round(x,3) for x in ext])
        except Exception as e:
            print(nm, 'not found', str(res)[:200])
    else:
        print(nm, 'err', str(rr.output)[:200])

