# Robot is now near the counter. Re-query candidate tools and the toolbox.
names = ['red toolbox', 'toolbox', 'black tool box', 'hammer', 'wrench', 'screwdriver', 'pliers',
         'drill', 'mallet', 'flashlight', 'saw', 'utility knife', 'tape measure', 'ruler', 'spanner']
poss = {}
for nm in names:
    rr = primitives.call(name='submit_capx_action', action='get_object_pose', native_api=True,
                         parameters={'object_name': nm, 'return_bbox_extent': True})
    if rr.ok:
        res = rr.output['native_api_result']
        try:
            pos = res[0]['values']; ext = res[2]['values']
            if pos is not None:
                poss[nm] = (pos, ext)
                print('FOUND', nm, [round(x,3) for x in pos], [round(x,3) for x in ext])
            else:
                print('none', nm)
        except Exception as e:
            print('err', nm, str(e)[:80])
print('total found', len(poss))

